"""PL-03 step 4: write the JSON report."""

from __future__ import annotations

import json
from collections.abc import Mapping, Sequence
from pathlib import Path

from risk.types import Drawdown, Report, TickerSummary


def write_report(
    summary: Sequence[TickerSummary], drawdowns: Sequence[Drawdown], out_path: str | Path
) -> Report:
    """`{"tickers": [...]}`, one row per ticker, sorted, written to `out_path` (REP-01)."""
    by_ticker = {drawdown.ticker: drawdown for drawdown in drawdowns}
    if {item.ticker for item in summary} != by_ticker.keys() or len(summary) != len(by_ticker):
        msg = "summary and drawdowns cover different tickers"
        raise ValueError(msg)
    rows = tuple(
        _row(item, by_ticker[item.ticker]) for item in sorted(summary, key=lambda s: s.ticker)
    )
    Path(out_path).write_text(json.dumps({"tickers": list(rows)}, indent=1))
    return Report(path=str(out_path), rows=rows)


def _row(summary: TickerSummary, drawdown: Drawdown) -> Mapping[str, object]:
    return {
        "ticker": summary.ticker,
        "ann_return": summary.ann_return,
        "ann_vol": summary.ann_vol,
        "sharpe": summary.sharpe,
        "last_vol": summary.last_vol,
        "max_drawdown": drawdown.depth,
        "peak_date": drawdown.peak_date,
        "trough_date": drawdown.trough_date,
    }

